class Solution {
public:
    std::vector<std::vector<int>> reconstructMatrix(int upper, int lower, std::vector<int>& colsum) {
        int n = colsum.size();
        std::vector<int> row0(n, 0), row1(n, 0);

        for (int i = 0; i < n; ++i) {
            if (colsum[i] == 2) {
                row0[i] = 1;
                row1[i] = 1;
                upper--;
                lower--;
            }
        }
        for (int i = 0; i < n; ++i) {
            if (colsum[i] == 1) {
                if (upper >= lower && upper > 0) {
                    row0[i] = 1;
                    upper--;
                } else if (lower > 0) {
                    row1[i] = 1;
                    lower--;
                } else {
                    return {};
                }
            }
        }
        if (upper != 0 || lower != 0) return {};
        return {row0, row1};
    }
};

class Solution {
    public java.util.List<java.util.List<Integer>> reconstructMatrix(int upper, int lower, int[] colsum) {
        int n = colsum.length;
        int[] row0 = new int[n];
        int[] row1 = new int[n];

        for (int i = 0; i < n; i++) {
            if (colsum[i] == 2) {
                row0[i] = 1;
                row1[i] = 1;
                upper--;
                lower--;
            }
        }
        for (int i = 0; i < n; i++) {
            if (colsum[i] == 1) {
                if (upper >= lower && upper > 0) {
                    row0[i] = 1;
                    upper--;
                } else if (lower > 0) {
                    row1[i] = 1;
                    lower--;
                } else {
                    return java.util.List.of();
                }
            }
        }
        if (upper != 0 || lower != 0) return java.util.List.of();

        java.util.List<Integer> l0 = new java.util.ArrayList<>(n);
        java.util.List<Integer> l1 = new java.util.ArrayList<>(n);
        for (int x : row0) l0.add(x);
        for (int x : row1) l1.add(x);
        return java.util.List.of(l0, l1);
    }
}

